css:
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: Arial, sans-serif;
    font-size: 11px;
    color: #000;
    line-height: 1.4;
}

.container {
    padding: 15px;
    width: 100%;
}

/* ---------------- Header Section ---------------- */
.header-section {
    display: table;
    width: 100%;
    border: 2px solid #000;
    margin-bottom: 15px;
}

.header-left {
    display: table-cell;
    width: 50%;
    padding: 15px;
    border-right: 2px solid #000;
    vertical-align: top;
}

.header-right {
    display: table-cell;
    width: 50%;
    padding: 15px;
    vertical-align: top;
}

.header-logo {
    height: 60px;
    margin-bottom: 10px;
}

.header-label {
    font-weight: bold;
    display: inline-block;
    width: 110px;
    vertical-align: top;
}

.header-value {
    display: inline-block;
    width: calc(100% - 115px);
    vertical-align: top;
}

.header-row {
    margin: 5px 0;
    display: block;
}

.title {
    text-align: center;
    font-size: 24px;
    font-weight: bold;
    margin: 10px 0;
    text-decoration: underline;
}

/* ---------------- Items Table ---------------- */
.items-table {
    width: 100%;
    border-collapse: collapse;
    margin: 15px 0;
}

.items-table th,
.items-table td {
    border: 1px solid #000;
    padding: 6px 8px;
    text-align: left;
}

.items-table th {
    background-color: #f5f5f5;
    font-weight: bold;
    font-size: 10px;
    text-align: center;
}

.items-table td {
    font-size: 10px;
}

.text-center {
    text-align: center !important;
}

.text-right {
    text-align: right !important;
}

.items-table .col-sr {
    width: 4%;
}

.items-table .col-part {
    width: 15%;
}

.items-table .col-qty {
    width: 8%;
}

.items-table .col-lpn {
    width: 12%;
}

.items-table .col-pallet {
    width: 10%;
}

.items-table .col-weight {
    width: 8%;
}

.items-table .col-dims {
    width: 7%;
}

.items-table .col-cbm {
    width: 12%;
}

/* Grouped rows styling */
.group-row {
    background-color: #ffffff;
}

.total-row {
    font-weight: bold;
    background-color: #f0f0f0;
}

.packing-note {
    margin: 10px 0;
    font-size: 11px;
}

/* ---------------- Footer Section ---------------- */
.footer-section {
    margin-top: 80px;
    display: table;
    width: 100%;
}

.footer-left,
.footer-right {
    display: table-cell;
    width: 50%;
    vertical-align: top;
}

.footer-label {
    font-weight: bold;
    margin-bottom: 5px;
}

.signature-line {
    margin-top: 50px;
}

.signature-field {
    display: inline-block;
    width: 45%;
    margin-right: 5%;
}

.signature-field label {
    display: block;
    margin-bottom: 3px;
}

.signature-field .line {
    border-bottom: 1px solid #000;
    width: 100%;
    height: 20px;
}

.footer-address {
    margin-top: 20px;
    text-align: center;
    font-size: 9px;
    border-top: 1px solid #000;
    padding-top: 10px;
}

.page-number {
    text-align: right;
    margin-top: 10px;
    font-size: 10px;
}

/* ---------------- Print Settings ---------------- */
@media print {
    @page {
        size: A4;
        margin: 10mm;
    }
    body {
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
    }
}
